import matmul from './matmul.js';

// Rows are grouped in the table in this order.
export const GROUPS = [
  ['dense', 'Dense arithmetic'],
  ['movement', 'Data movement'],
  ['sim', 'Simulation'],
  ['image', 'Imaging'],
  ['transform', 'Transforms'],
  ['render', 'Rendering'],
];

const WORKLOADS = [matmul];

const REQUIRED = ['id', 'name', 'params', 'tag', 'size', 'js', 'gpujs', 'reduce'];
const seen = new Set();
for (const w of WORKLOADS) {
  for (const key of REQUIRED) {
    if (w[key] === undefined) throw new Error(`workload ${w.id || '?'} is missing ${key}`);
  }
  if (seen.has(w.id)) throw new Error(`duplicate workload id: ${w.id}`);
  seen.add(w.id);
}

export default WORKLOADS;
